function answerFrame(ws: WebSocket, validation: ValidationResult): void {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
}

// The user listed is the connection's own, read from the session: a frame naming another user lists no one else.
async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendSessionList(ws, []);
    return;
  }
  try {
    const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
    sendSessionList(ws, summaries);
  } catch (error) {
    const detail = error instanceof Error ? error.message : 'Unknown error';
